const profileNames={marina:'Марина',vladlen:'Владлен'};
function switcher(){modal('<h2>Выбери профиль</h2>'+Object.entries(profileNames).map(([k,v])=>btn(v+(activeProfile===k?' · текущий':''),"switchProfile(\'"+k+"\')")).join(''))}
function switchProfile(k){if(!profileNames[k])return;persist();localStorage.setItem('sb.active',k);location.reload()}
function courseState(){return db.course??={unit:activeProfile==='marina'?3:0,reports:[],weak:[],session:null,minutes:90}}
function resumeCurrentSession(){if(courseState().session)return lessonScreen();startScheduledLesson()}
function resumeCourseSession(){const cs=courseState(),pending=cs.calendarSessions??={},saved=pending.resume;if(!saved)return;cs.session=saved;delete pending.resume;persist();lessonScreen()}
function makeDistractors(model,wrong,ask='') { const pool=[...(wrong||[])].map(x=>String(x).replace(/\s+/g,' ').trim()); const clean=String(model).replace(/\s+/g,' ').trim(); const v=clean.toLowerCase(); const irregular={leave:['leaves','left','leaving'],go:['goes','went','gone'],take:['takes','took','taken'],see:['sees','saw','seen'],do:['does','did','done'],be:['is','was','been'],have:['has','had','having'],get:['gets','got','gotten'],make:['makes','made','making'],come:['comes','came','coming'],say:['says','said','saying'],write:['writes','wrote','written'],read:['reads','read','reading'],run:['runs','ran','running'],eat:['eats','ate','eaten'],buy:['buys','bought','buying'],bring:['brings','brought','bringing'],think:['thinks','thought','thinking'],know:['knows','knew','known'],find:['finds','found','finding'],put:['puts','put','putting'],meet:['meets','met','meeting'],teach:['teaches','taught','teaching'],catch:['catches','caught','catching']}; let generated=[];if(clean.length>60){generated=['Not stated in the text.','The opposite is true.','This concerns a different detail.'];}else if(irregular[v])generated=irregular[v];else if(v.startsWith('the most ')){generated=['more '+clean.slice(9),'the least '+clean.slice(9),clean.slice(4)];}else if(v.endsWith('ed')){const base=v.endsWith('ied')?v.slice(0,-3)+'y':v.endsWith('d')?v.slice(0,-1):v;generated=[base,base+'s',base+'ing'];}else if(v.endsWith('ing')){const base=v.slice(0,-3);generated=[base, 'is '+clean, 'was '+clean];}else if(v.endsWith('e'))generated=[v+'s',v+'d',v.slice(0,-1)+'ing'];else if(v.endsWith('y'))generated=[v.slice(0,-1)+'ies',v+'ed',v+'ing'];else if(/^how to /i.test(clean))generated=[clean.replace(/^how to /i,'When to '),clean.replace(/^how to /i,'How can students '),clean.replace(/^how to /i,'How should the group ')];else if(/^(what|who|where|when|why|how)\b/i.test(clean))generated=[clean.replace(/^(what|who|where|when|why|how)\b/i,'When'),clean.replace(/^(what|who|where|when|why|how)\b/i,'Why'),clean.replace(/^(what|who|where|when|why|how)\b/i,'How')];else if(!v.includes(' '))generated=[v+'s',v+'ed',v+'ing'];else generated=[clean.replace(/\bthe\b/i,''),clean.replace(/\bnot\b/i,''),clean.replace(/\bto\b/i,'')];for(const x of generated.map(x=>String(x).replace(/\s+/g,' ').trim()))if(x&&!pool.includes(x)&&x!==clean)pool.push(x);const seen=new Set([clean]);const unique=pool.filter(x=>{x=String(x).trim();if(!x||seen.has(x))return false;seen.add(x);return true;}).slice(0,3);const fillers=['Not stated in the text.','The statement is unsupported.','This is not mentioned.','None of these choices.'];while(unique.length<3){const filler=fillers.find(x=>!seen.has(x));const value=filler||('Alternative '+(unique.length+1));seen.add(value);unique.push(value);}const all=[clean,...unique];let seed=Array.from(String(ask+clean)).reduce((n,c)=>n+c.charCodeAt(0),0);for(let i=all.length-1;i>0;i--){seed=(seed*9301+49297)%233280;let j=Math.floor(seed/233280*(i+1));[all[i],all[j]]=[all[j],all[i]];}return all; }
function selectItem(stage,title,ask,model,wrong,tip){return {stage,title,ask,model,choices:makeDistractors(model,wrong,ask),tip}}
function fixItem(u,stage=0){return {stage,title:'Исправь предложение',ask:u[5],model:u[6],tip:u[1],exact:true,tag:u[0]}}
function vocab(sc){return sc[1].split(';').map(x=>x.split('|'))}
function buildLesson(s) {
  const u = units[s.unit];
  const dayIndex = s.lessonDate ? Math.max(0, Math.round((Date.parse(s.lessonDate) - calendarStart) / calendarDay)) : s.unit;
  const week = Math.floor(dayIndex / 7);
  const level = s.unit < 12 ? 'A2' : s.unit < 30 ? 'B1' : 'B2';
  const scene = scenes[dayIndex % scenes.length];
  const words = vocab(scene);
  const items = [];
  // Always teach the day's grammar before showing exercises.
  items.push({stage:1,title:'Полная лекция · Lesson '+String(s.unit+1).padStart(2,'0')+' · '+u[0],info:u[1]+' '+grammarNotes[s.unit],examples:[u[6]],lecture:true,lectureUnit:s.unit});
  const warm = courseState().weak.filter(item => item.stage <= 2 && item.model && (item.exact || item.choices)).slice(-2);
  for (const item of warm) items.push({...item, stage:0, title:'Из прошлых ошибок'});
  // Interleave previously studied forms, varying the actual questions on return visits.
  for (let j = items.length; j < 5; j++) {
    const previous = Math.max(0, s.unit - 1 - (j % 3));
    const bank = grammarPractice[previous];
    const [ask, answer, wrong] = bank[(dayIndex + 3*j) % bank.length];
    items.push({...selectItem(0,units[previous][0],ask,answer,[wrong],grammarNotes[previous]),tag:units[previous][0]});
  }  const pool = grammarPractice[s.unit];
  const count = s.minutes <= 60 ? 3 : 5;
  for (let k = 0; k < count; k++) {
    const [ask,answer,wrong] = pool[(dayIndex * 3 + k) % pool.length];
    items.push(selectItem(1,'Выбери форму',ask,answer,[wrong],ask.replace('___',answer)+' — '+grammarNotes[s.unit]));
  }
  const [ask, model, tip] = contextualGrammar[s.unit];
  items.push({...fixItem(u,1),tip:grammarNotes[s.unit]}, {stage:1,title:'Заполни пропуск',ask,model,tip,exact:true});
  const rewrite = rewrites[s.unit];
  if (rewrite) items.push({stage:1,title:'Sentence Building',ask:rewrite[2],model:rewrite[1],exact:true,tip:grammarNotes[s.unit]});
  items.push({stage:1,title:'Своя фраза',ask:u[7],tip:grammarNotes[s.unit]});
  items.push({stage:2,title:scene[0],info:'Прочитай сочетания. Закрой список и вспомни, в каком контексте тебе пригодятся два из них.',examples:words.map(([en,ru,example])=>en+' — '+ru+'. '+example)});
  for (const j of [0,2,4]) items.push(selectItem(2,'Значение в контексте',words[j][2]+' → '+words[j][0],words[j][1],[words[j+1][1],words[(j+2)%6][1]],words[j][2]));
  items.push({stage:2,title:'Активный словарь',ask:'Imagine a situation involving '+scene[0]+'. Write two connected sentences using two expressions from the list.',tip:'Опиши конкретную ситуацию и проверь сочетаемость слов.',words:words.map(w=>w[0])});
  items.push({...selectItem(3,scene[0],scene[3],scene[4],scene.slice(5),scene[2]),audio:scene[2]});
  const listen = listeningBank[dayIndex % listeningBank.length];
  for (const [question,answer,...wrong] of listen[2]) items.push({...selectItem(3,listen[0],question,answer,wrong,listen[1]),audio:listen[1]});
  const interview = speakingBank[dayIndex % speakingBank.length];
  const support = level==='A2' ? 'Начни с двух предложений: прямой ответ и причина. Можно взять паузу.' : level==='B1' ? 'Сформулируй позицию, объясни причину и приведи один конкретный пример.' : 'Покажи, где твой аргумент особенно убедителен и при каком условии вывод меняется.';
  items.push({stage:4,title:'Listen and Repeat',audio:words[2][2],ask:'Repeat the sentence aloud.',model:words[2][2],tip:'Сравни ударные слова и окончания со своей записью.',repeat:true});
  items.push({stage:4,title:'Grammar into Speaking · '+u[0],ask:u[7],tip:support+' Используй конструкцию урока.'});
  for (const question of interview.slice(1)) items.push({stage:4,title:'Take an Interview · '+interview[0],ask:question,tip:support});
  items.push({stage:4,title:'Answer Expansion',ask:'Return to the question: '+interview[1]+' Give a fresh answer. Include one detail from your experience or a realistic example. Explain how it supports your point.',tip:support+' Сначала набросай три опорных слова. Сравни две записи.'});
  if (s.last === 'Reading') {
    const r = readingTasks[(week*3+Math.floor((dayIndex%7)/2))%readingTasks.length];
    items.push(r.length===4 ? {stage:5,title:r[0],source:r[1],ask:r[2],model:r[3],exact:true,tip:r[3]} : {...selectItem(5,r[0],r[2],r[3],r.slice(4),r[3]),source:r[1]});
    if (r.length>4) items.push({stage:5,title:'Подтверди вывод текстом',source:r[1],ask:'Find the words that support your previous answer. Explain the connection in your own words.',tip:'Укажи точные слова автора, затем одной фразой объясни, как они подтверждают ответ.'});
  } else {
    const sentences = sentenceWriting.filter(row=>row[0]===level);
    const writing = writingBank.filter(row=>row[1]===level && (row[0]==='Email'||row[0]==='Discussion'));
    const index = week*3+Math.floor((dayIndex%7)/2);
    const sentence = sentences[index % sentences.length];
    const task = writing[index % writing.length];
    items.push({stage:5,title:'Build a Sentence',ask:'Put the words in order: '+sentence[2],model:sentence[1],exact:true,tip:'Собери подлежащее и сказуемое. Для вопроса проверь место вспомогательного глагола.'});
    items.push({stage:5,title:task[0]==='Email'?'Write an Email':'Write for an Academic Discussion',ask:task[2],tip:task[0]==='Email'?'Назови адресата и цель. Убедись, что читатель понимает, какого действия ты ждёшь.':'Ответь на вопрос преподавателя и добавь свой аргумент. Покажи, как пример связан с твоей позицией.'});
  }
  return items;
}
function grammarWorkshop() {
  const cs=courseState();
  if (cs.session) return lessonScreen();
  const unit=Number($('#unitSelect').value), bank=grammarPractice[unit];
  const items=bank.map(([ask,answer,wrong])=>selectItem(1,units[unit][0],ask,answer,[wrong],ask.replace('___',answer)+' — '+grammarNotes[unit]));
  cs.session={id:crypto.randomUUID(),unit,diag:false,practice:true,last:'Grammar',pos:0,answers:[],draft:'',heard:false,started:Date.now(),minutes:30,items};
  persist();
  lessonScreen();
}
function buildDiagnostic(){let r=readingTasks[1],sc=scenes[1];return [selectItem(0,'Grammar','Yesterday the library ___ early.','closed',['closes','closing'],'Yesterday указывает на завершённое событие.'),{...selectItem(5,'Reading',r[2],r[3],r.slice(4),r[3]),source:r[1]},{...selectItem(3,'Listening',sc[3],sc[4],[sc[5],sc[6]],sc[2]),audio:sc[2]},{stage:4,title:'Speaking',ask:'Describe a place you enjoy visiting. What makes it special?',tip:'Добавь причину и одну деталь.'},{stage:5,title:'Writing',ask:'Write three sentences about a change you would like to see in your town. Explain why.',tip:'Сформулируй изменение и ожидаемый результат.'}]}
function startLesson(diag=false){let cs=courseState();if(activeProfile==="vladlen"&&!cs.reports.length&&!cs.skipDiagnostic)diag=true;const requested=cs.calendarRequest;delete cs.calendarRequest;if(cs.session){persist();return lessonScreen()}if(requested)diag=false;if(!diag&&!requested&&cs.unit>=units.length)return catalog();let s={id:crypto.randomUUID(),unit:requested?scheduledUnit(requested):cs.unit%units.length,lessonDate:requested,diag,last:requested?(new Date(requested+'T12:00:00Z').getUTCDay()%2?'Reading':'Writing'):(cs.reports.filter(x=>!x.diag).length%2?'Writing':'Reading'),pos:0,answers:[],draft:'',heard:false,started:Date.now(),minutes:requested?dayProgram(requested).minutes:cs.minutes};s.items=diag?buildDiagnostic():buildLesson(s);cs.session=s;persist();lessonScreen()}
function catalog(){let cs=courseState();modal('<h2>Мой курс</h2><p>Выбери тему и длину занятия. Маршрут можно менять между уроками.</p><label>Грамматика<select id="unitSelect">'+units.map((u,i)=>'<option value="'+i+'" '+(i===cs.unit?'selected':'')+'>'+esc(u[0])+'</option>').join('')+'</select></label><label>Плановое время<select id="duration">'+opts(['60','75','90'],String(cs.minutes))+'</select></label>'+btn(cs.session?'Продолжить текущее занятие':'Начать урок','catalogStart()','primary')+(cs.session?'':btn('Короткая диагностика · 5 заданий','startLesson(true)'))+(cs.session?'':btn('Вся практика выбранной темы','grammarWorkshop()'))+btn('Speaking interviews','interviewCatalog()')+reportList())}
function catalogStart(){let cs=courseState();if(!cs.session){cs.unit=Number($('#unitSelect').value);cs.minutes=Number($('#duration').value);persist()}startLesson()}
function reportList(){return courseState().reports.slice().reverse().map(r=>'<details><summary>'+esc(r.date+' · '+r.name)+'</summary><p>'+esc(r.summary)+'</p></details>').join('')}
const grammarTranslations = ["Она работает по воскресеньям?","Они сейчас готовят ужин.","Ей нужен билет.","Мы не поехали на автобусе.","Они купили билеты?","Художник рисовал в полдень.","Пока мы ели, зазвонил телефон.","Она написала два отчёта.","Я позвоню в офис.","Он может объяснить маршрут.","Она купила синий зонт.","Музей открывается в понедельник.","Если пойдёт дождь, мы останемся дома.","Если бы я знал ответ, я бы сказал тебе.","Мы купили несколько предметов мебели.","У меня есть несколько книг.","Так проще.","Она самая опытная студентка.","Он водит осторожно.","Я посетил Рим в прошлом году.","Он работает весь день.","Она уже ушла домой.","Они ждали несколько часов.","Завтра в восемь я буду заниматься.","К этому времени она уже напишет это.","Если нагреть лёд, он тает.","Если бы я знал, я бы пришёл.","Если бы я учился, сейчас я бы знал.","Результаты были опубликованы.","Проблему следует решить.","Он сказал, что может пойти.","Она спросила, где я был.","Книга, которую я прочитал, была полезной.","Моя сестра, которая живёт за границей, позвонила.","Мне нравится плавать.","Я избегаю водить машину ночью.","Возможно, она знает ответ.","Должно быть, он забыл.","Хотелось бы мне говорить свободно.","Раньше она здесь работала.","Он готов, не так ли?","Ты знаешь, когда это начинается?","Хотя было холодно, мы вышли.","Мы остались дома, потому что шёл дождь.","Редко мы видим такое.","Возвращаясь домой пешком, я заметил, что начинается дождь."];
const grammarDeepDive = ["Present Simple нужен для привычек, расписаний и фактов, которые считаются постоянными. В утверждении с he, she и it к смысловому глаголу добавляется окончание -s или -es. В вопросе и отрицании появляется does, поэтому окончание возвращается к базовой форме: Does she work? She does not work. Слова usually, often, never и every day помогают увидеть регулярность.","Present Continuous строится с помощью am, is или are и смыслового глагола с -ing. Он описывает действие прямо сейчас, временную ситуацию вокруг настоящего момента, изменение или заранее организованную встречу. В отрицании not ставится после be, а в вопросе be переносится перед подлежащим. Обычно глаголы состояния, например know и need, не используют в Continuous.","Оба времени относятся к настоящему, но отвечают на разные вопросы. Present Simple показывает, что происходит обычно или является фактом; Present Continuous — что происходит сейчас или временно. Сравни: I work in a library — это моя обычная работа; I am working from home this week — только временная ситуация. Некоторые глаголы меняют значение в зависимости от формы.","Past Simple описывает завершённое событие в прошлом, особенно если названо законченное время: yesterday, last week, in 2022. Правильные глаголы обычно получают -ed, неправильные нужно учить по второй форме. Для большинства глаголов вопросы и отрицания строятся с did, после которого используется начальная форма. Глагол be образует вопросы и отрицания самостоятельно.","Главное — различать вторую форму глагола и конструкцию did. В утверждении говорим They bought the tickets, но в вопросе Did they buy the tickets? В обоих случаях время уже обозначено: в первом — формой bought, во втором — вспомогательным did. Не добавляй окончание прошедшего времени к глаголу после did.","Past Continuous показывает действие, которое было в процессе в определённый момент прошлого. Формула: was или were + глагол с -ing; выбор was/were зависит от подлежащего. В рассказе эта форма часто создаёт фон, на котором происходит короткое событие в Past Simple. Глаголы состояния обычно остаются в простой форме.","Когда одно действие прерывает другое, длительный процесс обычно ставится в Past Continuous, а короткое событие — в Past Simple. While часто вводит длительный фон, when — момент или событие, но это не жёсткое правило: ориентируйся на смысл. Если два процесса шли одновременно, оба можно поставить в Past Continuous.","Present Perfect соединяет прошлое с настоящим: важен опыт, результат или период, который ещё не закончился. Формула — have/has + третья форма глагола. Частые маркеры: ever, never, already, yet, just, so far, recently. Если событие привязано к законченному времени вроде yesterday или last year, обычно нужен Past Simple.","Will часто используется для решения, принятого в момент разговора, обещания или прогноза. Be going to подходит для уже сформированного намерения и прогноза на основе видимых признаков. Present Continuous часто обозначает личную договорённость, а Present Simple — расписание. Выбирай форму по смыслу, а не только по слову tomorrow.","После can, could, should, must, may и might используется начальная форма глагола без to и без окончания -s. Отрицание строится добавлением not после модального глагола, вопрос — переносом модального глагола перед подлежащим. Must not означает запрет, а do not have to — отсутствие необходимости: это разные значения.","A и an вводят один исчисляемый предмет, который упоминается впервые или не является конкретным для собеседника. Выбор зависит от звука в начале следующего слова, а не от буквы: an hour, a university. The используется, когда понятно, о каком именно объекте идёт речь. Во множественном числе и с неисчисляемыми существительными для общего значения артикль часто не нужен.","Предлоги времени удобно запоминать как at для точного времени, on для дней и дат, in для месяцев, лет и длительных периодов. Для места значения зависят от того, говорим ли мы о точке, поверхности или пространстве. Помимо общих правил есть устойчивые сочетания: depend on, interested in, good at. Их лучше учить вместе с примером.","First Conditional описывает реальное или вполне возможное условие в будущем. После if ставится Present Simple, а результат обычно выражается will + начальная форма: If it rains, we will stay home. Не ставь will сразу после if в обычном условном предложении. Unless часто можно понимать как if not.","Second Conditional нужен для воображаемой или маловероятной ситуации в настоящем либо будущем. После if используется форма Past Simple, а в главной части — would + начальная форма. Прошедшая форма здесь не означает прошлое время, а показывает дистанцию от реальности. В гипотетических ситуациях часто используется were: If I were you.","Исчисляемые существительные можно посчитать: one book, two books; у них есть форма единственного и множественного числа. Неисчисляемые обозначают массу, материал или абстрактное понятие и обычно не получают -s: information, furniture, advice. Чтобы посчитать их, добавь единицу измерения или часть: a piece of advice, two items of furniture.","Quantifiers показывают количество и согласуются с типом существительного. Many и a few употребляются с исчисляемыми во множественном числе, much и a little — с неисчисляемыми. A few и a little обычно звучат позитивнее, чем few и little: они подчёркивают, что некоторое количество всё-таки есть. Some часто встречается в утверждениях, any — в вопросах и отрицаниях.","Сравнительная степень сопоставляет два объекта: короткие прилагательные обычно получают -er, длинные используют more, затем ставится than. Есть неправильные формы: good — better, bad — worse. Конструкции as ... as показывают равенство, а much или far усиливают сравнение. Не используй одновременно more и окончание -er.","Превосходная степень выделяет один объект среди группы. Для коротких прилагательных обычно используется -est, для длинных — the most; перед формой чаще всего нужен the. Запомни исключения good — the best и bad — the worst. В конструкции one of the best после прилагательного ставится существительное во множественном числе.","Наречие обычно уточняет, как, когда, где или насколько происходит действие; прилагательное описывает существительное. Многие наречия образуются добавлением -ly, но есть исключения: fast, hard, well. Позиция зависит от типа наречия: usually часто стоит перед смысловым глаголом, но после be. Hard и hardly имеют разные значения.","Past Simple используется с завершённым временем в прошлом: yesterday, in 2020, last summer. Present Perfect важен, когда прошлое связано с настоящим: жизненный опыт, результат или незаконченный период. Сравни I visited Rome last year и I have visited Rome twice. Не смешивай маркеры законченного времени с Present Perfect.","Present Perfect Continuous образуется как have/has been + глагол с -ing и подчёркивает длительность или повторяемость процесса до настоящего момента. For указывает продолжительность, since — точку начала. Часто форма объясняет видимый результат: усталость после работы или мокрую одежду после дождя. Для глаголов состояния чаще нужен Present Perfect Simple.","Past Perfect показывает, что одно действие произошло раньше другого события в прошлом. Формула — had + третья форма глагола; она помогает ясно расставить события по времени. Часто встречается с by the time, already и before. Не нужно ставить Past Perfect в каждом предложении о прошлом, если последовательность и так очевидна.","Past Perfect Continuous подчёркивает, как долго процесс продолжался до определённого момента в прошлом. Формула — had been + глагол с -ing. Сравни: had worked сообщает о факте или результате, had been working выделяет длительность и сам процесс. For и since помогают назвать продолжительность.","Future Continuous описывает действие, которое будет происходить в конкретный момент будущего: will be + глагол с -ing. Часто используется с at this time tomorrow или at eight tonight. Эта форма также помогает вежливо спрашивать о планах: Will you be using the room? Она не обязательно подчёркивает намерение.","Future Perfect показывает, что действие завершится к определённому будущему сроку. Формула — will have + третья форма глагола. By Friday означает не позднее пятницы, то есть крайний срок; until Friday подчёркивает продолжение действия до пятницы. Не путай by и until.","Zero Conditional описывает закономерности, научные факты и повторяющиеся результаты. В обеих частях обычно используется Present Simple: If you heat ice, it melts. Вместо if часто подходит when, если речь о предсказуемом результате. Не ставь will в обычной части условия, когда описываешь общий факт.","Third Conditional описывает нереальное прошлое — ситуацию, которая не произошла, и воображаемый результат. В условной части используется if + had + третья форма, в результате — would have + третья форма. Можно использовать could have или might have, если речь о возможности. Эта конструкция часто выражает сожаление или анализ решения.","Mixed Conditionals связывают разные временные планы: например, нереальное прошлое условие с результатом в настоящем. Типичная модель: If + Past Perfect, would + начальная форма. Сначала определи, когда относится условие, а когда результат, и только затем выбирай форму. Не подбирай обе части механически по одному шаблону.","Passive Voice нужен, когда важнее действие или объект, над которым оно совершается, чем исполнитель. Формула — подходящая форма be + третья форма смыслового глагола: is made, was built, has been published. Время выражается через be, а by добавляется, если важно назвать исполнителя. Не забывай согласовать be с подлежащим.","После модального глагола пассив строится как modal + be + третья форма: must be checked, should be completed. Для предположения о прошлом возможна конструкция modal + have been + третья форма. Важно не ставить активную форму смыслового глагола после модального глагола, если подлежащее испытывает действие.","В косвенной речи мы передаём чужие слова, не цитируя их дословно. После глагола в прошедшем времени часто происходит сдвиг времени назад: am становится was, will — would, can — could. Также меняются местоимения и указатели времени, если изменился контекст. Say обычно не требует адресата, tell обычно требует: tell me.","Косвенный вопрос сохраняет порядок слов обычного утверждения: He asked where I lived, а не where did I live. Вопросы да/нет вводятся if или whether. Если вводная часть уже содержит вопросительную конструкцию, не делай вторую инверсию. Сдвиг времени зависит от контекста и времени глагола сообщения.","Relative Clauses уточняют, о каком человеке или предмете идёт речь. Who относится к людям, which — к предметам, that может использоваться в определительных придаточных обоих типов. Если относительное местоимение является дополнением, его иногда можно опустить. Если оно является подлежащим, опускать его нельзя.","Non-defining Relative Clauses добавляют дополнительную информацию, без которой основная мысль остаётся понятной. Такой оборот выделяется запятыми, обычно использует who или which и не допускает that. В устной речи эта информация произносится как отдельное уточнение. Не путай её с defining clause, которая необходима для идентификации предмета.","После некоторых глаголов используется герундий с -ing, после других — инфинитив с to. Например, enjoy doing, decide to do; после предлогов обычно нужен -ing. Универсального правила для всех глаголов нет, поэтому полезно запоминать устойчивые модели вместе с короткими примерами.","Некоторые глаголы меняют значение в зависимости от следующей формы: stop doing — прекратить действие, stop to do — остановиться, чтобы выполнить другое действие. Remember doing — помнить о прошлом опыте, remember to do — не забыть выполнить задачу. После make и let в активной конструкции используется инфинитив без to, но в пассиве to возвращается.","Modal Deduction выражает вывод по имеющимся признакам, а не обязанность. Must показывает высокую уверенность, might или may — возможность, can't — уверенность, что вывод неверен. После модального глагола используется начальная форма, а для состояния — be: She must be tired. Выбирай модальный глагол по степени уверенности.","Для вывода о прошлом используй modal + have + третья форма: must have forgotten, might have left, can't have known. Must have означает сильное предположение, might have — возможность, can't have — невозможность. Не путай эту конструкцию с обычным прошедшим временем и не используй вторую форму после have.","Wish и If only помогают говорить о желаемом, но нереальном положении дел. Для настоящего используется форма Past Simple: I wish I had more time; для сожаления о прошлом — Past Perfect: I wish I had studied. Wish + would часто выражает раздражение или желание, чтобы ситуация изменилась.","Used to + начальная форма описывает привычку или состояние, которые были в прошлом, но сейчас обычно уже не актуальны. Be used to + существительное или -ing означает, что человек привык к чему-то. Get used to описывает процесс привыкания. После be used to нельзя ставить обычный инфинитив без -ing.","Question Tags — короткие хвостовые вопросы для проверки информации или приглашения к согласию. После утвердительного предложения обычно идёт отрицательный хвост, после отрицательного — утвердительный. В хвосте повторяется вспомогательный или модальный глагол и местоимение. Запомни особые формы aren't I? и shall we? после Let's.","Indirect Questions звучат вежливее прямых вопросов, особенно в просьбах о помощи и информации. После Could you tell me или Do you know используется прямой порядок слов: where the station is. Для вопросов да/нет нужны if или whether. Не переноси инверсию из прямого вопроса внутрь косвенного.","Although и even though вводят полноценное предложение с подлежащим и сказуемым. Despite и in spite of требуют существительное, местоимение или форму -ing; после них нельзя сразу ставить обычное предложение без of the fact that. However часто связывает два самостоятельных предложения и выделяется пунктуацией.","Because вводит причину с полноценным предложением, because of — причину в форме существительного или именной группы. So показывает результат, therefore — логический вывод и обычно звучит формальнее. Избегай двойной связи вроде because ... so в одном стандартном предложении.","Inversion после отрицательных или ограничительных выражений в начале предложения усиливает акцент и часто используется в формальном стиле. После Never, Rarely, Seldom и Not only вспомогательный глагол ставится перед подлежащим. Если вспомогательного глагола нет, в Present Simple и Past Simple добавляется do или did.","Participle Clauses сокращают придаточные предложения и делают письменную речь компактнее. Форма -ing обычно показывает активное или одновременное действие, третья форма — пассивное значение, Having + третья форма — действие, завершившееся раньше. Исполнитель причастного оборота должен совпадать с подлежащим главной части, иначе получится dangling modifier."];
function lectureHTML(unit){
 const u=units[unit],note=grammarNotes[unit]||'',practice=grammarPractice[unit]||[],ctx=contextualGrammar[unit]||[],translation=grammarTranslations[unit]||'',detail=grammarDeepDive[unit]||'';
 const number=String(unit+1).padStart(2,'0'),level=unit<12?'A2':unit<30?'B1':'B2';
 const examples=practice.slice(0,5).map(([ask,answer,wrong],i)=>'<li><b>Example '+(i+1)+'</b><p lang="en">'+esc(ask.replace(/___/g,answer))+'</p><small>Target form: '+esc(answer)+'. Compare with: '+esc(wrong)+'</small></li>').join('');
 const pastSimpleReview='<section class="lecture-section"><h4>1. Вспомни основу Past Simple</h4><div class="grammar-formula-grid"><div class="grammar-formula"><b>Утверждение</b><strong>Subject + V2</strong><span>We found the answer.</span><small>Мы нашли ответ.</small></div><div class="grammar-formula"><b>Отрицание</b><strong>Subject + didn’t + V1</strong><span>We didn’t find it.</span><small>Мы не нашли его.</small></div><div class="grammar-formula"><b>Вопрос</b><strong>Did + subject + V1?</strong><span>Did you find it?</span><small>Ты нашла его?</small></div></div><p>Перед тем как продолжить, проверь себя: где стоит V2, а где после did обязательно нужна V1?</p></section><section class="lecture-section"><h4>2. Повтори неправильные глаголы</h4><p>У неправильных глаголов форму Past Simple нельзя получить простым добавлением -ed. Учим пару V1 → V2 и сразу используем её в предложении:</p><div class="irregular-list"><span>go → <b>went</b> · идти</span><span>come → <b>came</b> · приходить</span><span>see → <b>saw</b> · видеть</span><span>take → <b>took</b> · брать</span><span>make → <b>made</b> · делать</span><span>buy → <b>bought</b> · покупать</span><span>find → <b>found</b> · находить</span><span>think → <b>thought</b> · думать</span><span>have → <b>had</b> · иметь</span><span>write → <b>wrote</b> · писать</span><span>get → <b>got</b> · получать</span><span>leave → <b>left</b> · уходить</span></div></section><section class="lecture-section"><h4>3. Не допускай двойного Past</h4><div class="grammar-warning"><b>Неправильно:</b> Did you went? / She didn’t bought it.<br><b>Правильно:</b> Did you go? / She didn’t buy it.</div><p>В утверждении используем V2: She bought it. В вопросе и отрицании время уже выражено did, поэтому ставим V1: Did she buy it? She didn’t buy it.</p></section><section class="lecture-section"><h4>4. Собери короткую историю</h4><blockquote lang="en">Yesterday I woke up late, missed the bus, took a taxi and arrived just in time.</blockquote><p class="correct-model"><b>Перевод:</b> Вчера я поздно проснулась, опоздала на автобус, взяла такси и приехала как раз вовремя.</p><p>Заметь: несколько завершённых действий идут друг за другом. Для каждого смыслового глагола в утвердительной форме используем Past Simple.</p></section><section class="lecture-section"><h4>5. Самостоятельная речь</h4><p lang="en">What did you find, buy or learn on your last day out?</p><p>Расскажи о реальном событии в 4–6 предложениях. Используй минимум три неправильных глагола и один вопрос с did. Сначала сформулируй ответ самостоятельно — подсказка и образец появятся только после проверки.</p></section>';
 const pastSimple=unit===4?pastSimpleReview:unit===3?'<section class="lecture-section"><h4>1. Когда используем Past Simple</h4><p>Past Simple описывает действие или событие, которое произошло и завершилось в прошлом. Мы говорим о факте, последовательности событий или прошлом состоянии. Время действия обычно уже закончилось.</p><p class="lecture-example" lang="en">I visited my friend yesterday. — Я навестила подругу вчера.</p></section><section class="lecture-section"><h4>2. Как строится Past Simple</h4><div class="grammar-formula-grid"><div class="grammar-formula"><b>Утверждение</b><strong>Subject + V2</strong><span>I watched a film.</span><small>Я посмотрела фильм.</small></div><div class="grammar-formula"><b>Отрицание</b><strong>Subject + did not + V1</strong><span>I did not watch TV.</span><small>Я не смотрела телевизор.</small></div><div class="grammar-formula"><b>Вопрос</b><strong>Did + subject + V1?</strong><span>Did you watch it?</span><small>Ты это смотрела?</small></div></div><p><b>Самое важное:</b> в отрицании и вопросе прошедшее время уже показывает <b>did</b>, поэтому основной глагол возвращается в начальную форму V1.</p></section><section class="lecture-section"><h4>3. Правильные и неправильные глаголы</h4><p>У правильных глаголов обычно добавляем <b>-ed</b>: work → worked, clean → cleaned. Если глагол заканчивается на -e, добавляем только -d: live → lived. Если согласная + y, меняем y на ied: study → studied. В некоторых коротких глаголах удваивается последняя согласная: stop → stopped.</p><p>Неправильные глаголы не образуют Past Simple по общему правилу — их вторую форму нужно запоминать:</p><div class="irregular-list"><span>go → <b>went</b></span><span>have → <b>had</b></span><span>make → <b>made</b></span><span>see → <b>saw</b></span><span>buy → <b>bought</b></span><span>take → <b>took</b></span><span>write → <b>wrote</b></span><span>find → <b>found</b></span></div></section><section class="lecture-section"><h4>4. Вопросы и отрицания с did</h4><p>Вспомогательный глагол <b>did</b> одинаковый для I, you, he, she, it, we и they. После did / didn’t всегда ставим V1:</p><ul><li lang="en">She didn’t go to class. — Она не пошла на занятие.</li><li lang="en">Did he call you? — Он тебе звонил?</li><li lang="en">Where did they stay? — Где они остановились?</li></ul><div class="grammar-warning"><b>Не смешивай две формы:</b> They bought a ticket. / Did they buy a ticket? Нельзя: Did they bought…?</div></section><section class="lecture-section"><h4>5. Глагол to be: was / were</h4><p><b>Was</b> используется с I / he / she / it; <b>were</b> — с you / we / they. У be нет did:</p><ul><li lang="en">I was tired. — Я устала.</li><li lang="en">They were at home. — Они были дома.</li><li lang="en">Was she late? — Она опоздала?</li><li lang="en">We weren’t ready. — Мы не были готовы.</li></ul></section><section class="lecture-section"><h4>6. Слова-маркеры времени</h4><div class="time-marker-list"><span>yesterday — вчера</span><span>last night / week / year — прошлой ночью / неделе / году</span><span>two days ago — два дня назад</span><span>in 2024 — в 2024 году</span><span>when I was a child — когда я была ребёнком</span></div><p>Если указан законченный момент прошлого — например, yesterday или last year, — обычно нужен Past Simple.</p></section>':'<section class="lecture-section"><h4>1. Когда используется эта конструкция</h4><p>'+esc(detail)+'</p></section><section class="lecture-section"><h4>2. Основное правило</h4><p>'+esc(u[1])+'</p></section>';
 return '<article class="grammar-lecture"><div class="lesson-kicker">LESSON '+number+' <span>· '+level+'</span></div><h3>'+esc(u[0])+'</h3>'+pastSimple+'<section class="lecture-section"><h4>'+(unit===3?'7.':unit===4?'6.':'3.')+' Подробное объяснение и нюансы</h4><p>'+esc(detail)+'</p><p>'+esc(note)+'</p></section><section class="lecture-section"><h4>'+(unit===3?'8.':unit===4?'7.':'4.')+' Пример и перевод</h4><blockquote lang="en">'+esc(u[6])+'</blockquote><p class="correct-model"><b>Перевод:</b> '+esc(translation)+'</p></section><section class="lecture-section"><h4>'+(unit===3?'9.':unit===4?'8.':'5.')+' Типичная ошибка и исправление</h4><div class="hist"><p class="wrong-example" lang="en">'+esc(u[5])+'</p><p class="correct-model" lang="en">'+esc(u[6])+'</p><p>'+esc(note)+'</p></div></section><section class="lecture-section"><h4>'+(unit===3?'10.':unit===4?'9.':'6.')+' Попробуй применить правило</h4><p>'+esc(u[7])+'</p>'+(ctx.length?'<p>'+esc(ctx[0])+'</p><blockquote lang="en">'+esc(ctx[1])+'</blockquote><p class="note">'+esc(ctx[2]||'')+'</p>':'')+'</section><section class="lecture-section"><h4>Проверь себя на примерах</h4><ul>'+examples+'</ul><p class="note">Сначала прочитай правило и примеры. Не торопись открывать задания: попробуй объяснить правило своими словами, а затем переходи к практике.</p></section></article>';
}
